contract:
// Schets, geen code van v1.
track[n] = {
  drager,          // { soort: 'leeg' | 'nummer' | 'instrument' | 'sampler', … }
  strip,           // trim, eq{laag,mid,hoog,kill}, effect(rack), filter, fader, sends{a,b}, kant, cue
  transport,       // alleen nummer: cues, loops, beatjump, koppeling (onderdeel 1)
  ontvang(gebeurtenis, t),  // noot | pad | hotcue | sectie, t op de klok
}

// buiten de engine, één plek:
inhoud[n] = { soort, nummerId | instrument, herkomst, laad: { nr, stand: 'laadt' | 'klaar' | 'mislukt' } }

// op de bus:
laad(n, nummerId)        // -> 'laad.begin', 'laad.klaar' { grid, hotcues, toon, secties, pads, rack, layout }
zetDrager(n, soort)      // instrument, sampler, leeg; klikvrij; spelend = tweede druk

// strip: drager -> (stemkanalen op aanvraag) -> trim -> eq -> effect -> filter -> fader
//        -> sends a/b (na de fader) -> kant A|B|thru -> master
// cue tapt na het filter, vóór de fader; één bron voor de fadergain voedt alle afnemers
